use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Num(f64),
    Ident(String),
    Op(char),
    LParen,
    RParen,
}

fn tokenize(src: &str) -> Result<Vec<Tok>, String> {
    let chars: Vec<char> = src.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() {
            i += 1;
        } else if c.is_ascii_digit() || c == '.' {
            let start = i;
            while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                i += 1;
            }
            let text: String = chars[start..i].iter().collect();
            out.push(Tok::Num(text.parse().map_err(|_| format!("bad number {text:?}"))?));
        } else if c.is_alphabetic() || c == '_' {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            out.push(Tok::Ident(chars[start..i].iter().collect()));
        } else {
            out.push(match c {
                '+' | '-' | '*' | '/' | '^' => Tok::Op(c),
                '(' => Tok::LParen,
                ')' => Tok::RParen,
                _ => return Err(format!("unexpected '{c}'")),
            });
            i += 1;
        }
    }
    Ok(out)
}

struct Parser<'a> {
    toks: Vec<Tok>,
    pos: usize,
    vars: &'a HashMap<String, f64>,
}

impl Parser<'_> {
    fn peek(&self) -> Option<&Tok> {
        self.toks.get(self.pos)
    }

    fn next(&mut self) -> Option<Tok> {
        let t = self.toks.get(self.pos).cloned();
        self.pos += 1;
        t
    }

    fn expr(&mut self) -> Result<f64, String> {
        let mut v = self.term()?;
        while let Some(Tok::Op(op @ ('+' | '-'))) = self.peek().cloned() {
            self.next();
            let r = self.term()?;
            v = if op == '+' { v + r } else { v - r };
        }
        Ok(v)
    }

    fn term(&mut self) -> Result<f64, String> {
        let mut v = self.power()?;
        while let Some(Tok::Op(op @ ('*' | '/'))) = self.peek().cloned() {
            self.next();
            let r = self.power()?;
            if op == '*' {
                v *= r;
            } else {
                if r == 0.0 {
                    return Err("division by zero".into());
                }
                v /= r;
            }
        }
        Ok(v)
    }

    fn power(&mut self) -> Result<f64, String> {
        let base = self.unary()?;
        if let Some(Tok::Op('^')) = self.peek() {
            self.next();
            let exp = self.power()?;
            return Ok(base.powf(exp));
        }
        Ok(base)
    }

    fn unary(&mut self) -> Result<f64, String> {
        if let Some(Tok::Op('-')) = self.peek() {
            self.next();
            return Ok(-self.unary()?);
        }
        self.atom()
    }

    fn atom(&mut self) -> Result<f64, String> {
        match self.next() {
            Some(Tok::Num(n)) => Ok(n),
            Some(Tok::Ident(name)) => self.vars.get(&name).copied().ok_or(format!("unknown name '{name}'")),
            Some(Tok::LParen) => {
                let v = self.expr()?;
                match self.next() {
                    Some(Tok::RParen) => Ok(v),
                    other => Err(format!("expected ')' but found {other:?}")),
                }
            }
            other => Err(format!("expected a value but found {other:?}")),
        }
    }
}

fn eval(src: &str, vars: &HashMap<String, f64>) -> Result<f64, String> {
    let toks = tokenize(src)?;
    let mut p = Parser { toks, pos: 0, vars };
    let v = p.expr()?;
    if p.pos < p.toks.len() {
        return Err(format!("unexpected {:?} after the expression", p.toks[p.pos]));
    }
    Ok(v)
}

unitTests:
use std::collections::HashMap;

fn ev(s: &str) -> Result<f64, String> { eval(s, &HashMap::new()) }

test("precedence and brackets", || {
    check_eq(ev("2 + 3 * 4"), Ok(14.0));
    check_eq(ev("(2 + 3) * 4"), Ok(20.0));
    check_eq(ev("10 - 4 - 3"), Ok(3.0));
    check_eq(ev("8 / 2 / 2"), Ok(2.0));
});

test("powers group from the right, unary minus", || {
    check_eq(ev("2 ^ 3 ^ 2"), Ok(512.0));
    check_eq(ev("-2 ^ 2"), Ok(4.0));
    check_eq(ev("--3"), Ok(3.0));
    check_eq(ev("2 * -3"), Ok(-6.0));
});

test("variables", || {
    let vars = HashMap::from([("x".to_string(), 5.0), ("rate".to_string(), 0.5)]);
    check_eq(eval("x * rate + 1", &vars), Ok(3.5));
    check_eq(eval("y + 1", &vars), Err("unknown name 'y'".to_string()));
});

test("errors", || {
    check_eq(ev("1 / (2 - 2)"), Err("division by zero".to_string()));
    for bad in ["1 +", "(1 + 2", "1 2", "", "*3", "2 $ 3"] {
        check(ev(bad).is_err());
    }
});

